defp preset_amount_copy(5_000), do: {"Pemantik chat", "Buka dukungan", false}
defp preset_amount_copy(10_000), do: {"Naikkan energi", "Paling sering dipilih", true}
defp preset_amount_copy(25_000), do: {"Masuk spotlight", "Support maksimal", false}

defp preset_amount_copy(_amount), do: {"Support", "Terima kasih", false}

defp amount_option_classes(selected?, recommended?)

input.new_string:
body {
  background: transparent;
  color: var(--color-text);
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: 1.6;
  letter-spacing: 0.01em;
  font-kerning: normal;
}

input.old_string:
body {
  background: transparent;
  color: var(--color-text);
  font-family: var(--font-sans);
}

input.new_string:
  :focus-visible {
    outline: 2px solid color-mix(in oklch, var(--color-accent) 70%, white 0%);
    outline-offset: 3px;
  }
}

@layer components {
  /* Donor / product type ramp — fixed rem, ~1.2 ratio between steps */
  .type-display {
    font-family: var(--font-display), ui-sans-serif, system-ui, sans-serif;
    font-size: 2.25rem;
    font-weight: 600;
    line-height: 1.15;
    letter-spacing: -0.03em;
    text-wrap: balance;
  }

  @media (min-width: 640px) {
    .type-display {
      font-size: 2.5rem;
    }
  }

  .type-lead {
    max-width: 65ch;
    font-size: 1rem;
    line-height: 1.6;
    letter-spacing: 0.01em;
  }

  .type-label {
    font-size: 0.875rem;
    font-weight: 600;
    letter-spacing: 0.02em;
    color: var(--color-text-muted);
  }

  .type-body-muted {
    font-size: 1rem;
    line-height: 1.6;
    letter-spacing: 0.01em;
    color: var(--color-text-muted);
  }

  .type-amount-lg {
    font-size: 1.5rem;
    font-weight: 600;
    line-height: 1.2;
    letter-spacing: -0.02em;
    font-variant-numeric: tabular-nums;
    color: var(--color-text);
  }

  @media (min-width: 640px) {
    .type-amount-lg {
      font-size: 1.875rem;
    }
  }

  .type-amount-md {
    font-size: 1.125rem;
    font-weight: 600;
    line-height: 1.25;
    letter-spacing: -0.02em;
    font-variant-numeric: tabular-nums;
    color: var(--color-text);
  }

  .type-status {
    font-size: 0.875rem;
    font-weight: 600;
    color: var(--color-text-muted);
  }

  .type-field {
    font-size: 1rem;
    line-height: 1.5;
    letter-spacing: 0.01em;
  }
}

input.old_string:
  :focus-visible {
    outline: 2px solid color-mix(in oklch, var(--color-accent) 70%, white 0%);
    outline-offset: 3px;
  }
}
